# -*- coding: utf-8 -*-
from docx.shared import Pt
from docx.enum.text import WD_ALIGN_PARAGRAPH

def build_chapter1(doc, add_h, add_p, add_fig):
    add_h("CHƯƠNG 1: TỔNG QUAN TÀI LIỆU VÀ CƠ SỞ LÝ LUẬN", level=1, align=WD_ALIGN_PARAGRAPH.CENTER)

    add_h("1.1. Tổng quan nghiên cứu mô phỏng ngập lụt trên thế giới và tại Việt Nam", level=2)
    add_h("1.1.1. Tiến trình phát triển mô hình toán thủy lực trên thế giới", level=3)
    add_p("Mô phỏng ngập lụt bằng mô hình toán là một nhánh nghiên cứu chuyên sâu của thủy lực học tính toán (Computational Hydraulics) và thủy văn môi trường, đóng vai trò là công cụ cốt lõi trong việc dự báo, đánh giá hiểm họa và quy hoạch quản lý rủi ro thiên tai. Lịch sử phát triển của các mô hình thủy lực mô phỏng dòng chảy lũ trên thế giới có thể được chia thành bốn thời kỳ tiến hóa rõ rệt:")
    add_p("1. Thời kỳ mô hình thủy lực một chiều (1D Hydrodynamic Models):")
    add_p("Khởi đầu từ những năm 1970 và 1980 với sự ra đời của các chương trình tính toán số như HEC-2, HEC-RAS 1D (thuộc Trung tâm Kỹ thuật Thủy văn Quân đội Hoa Kỳ - USACE) [10], MIKE 11 (Viện Thủy lực Đan Mạch - DHI), và ISIS (sau này là Flood Modeller - Anh Quốc). Các mô hình này giải hệ phương trình Saint-Venant 1 chiều mô tả dòng chảy dọc theo trục chính của lòng sông. Giả thiết cơ bản của mô hình 1D là mực nước và lưu lượng chỉ biến đổi theo phương dọc dòng chảy (phương x), các thành phần vận tốc theo phương ngang và phương đứng bị bỏ qua. Dù có ưu thế vượt trội về tốc độ tính toán và chỉ yêu cầu dữ liệu mặt cắt ngang thưa thớt, mô hình 1D bộc lộ những khiếm khuyết mang tính bản chất khi nước lũ dâng cao tràn qua bờ đê và tỏa rộng ra các vùng trũng đồng bằng. Khi tràn bờ, nước lũ chảy theo nhiều hướng phức tạp, phụ thuộc vào vi địa hình và độ dốc mặt đất; việc áp đặt dòng chảy 1D trên bãi tràn dẫn đến việc ước tính sai lệch nghiêm trọng cả về diện tích ngập, độ sâu ngập lẫn thời gian lưu chuyển sóng lũ.")
    add_p("2. Thời kỳ mô hình bán hai chiều và mô hình 1D-2D tích hợp (Quasi-2D and Coupled 1D-2D Models):")
    add_p("Để giải quyết hạn chế của mô hình 1D trên bãi tràn mà vẫn tiết kiệm tài nguyên tính toán, các mô hình bán 2 chiều ra đời vào thập niên 1990 (tiêu biểu như phương pháp ô ngập lụt - Storage Cell approach trong HEC-RAS 1D hay SOBEK). Bãi tràn được chia thành các ô trũng (cells) có mối liên hệ thủy lực với nhau và với lòng sông chính qua các công trình tràn hoặc phương trình cống ngầm. Tiếp đó, các mô hình tích hợp 1D-2D liên kết động (Coupled 1D-2D) như MIKE FLOOD ra đời, trong đó lòng dẫn chính được mô phỏng 1D còn bãi tràn được mô phỏng 2D bằng phương pháp sai phân hữu hạn. Tuy nhiên, việc thiết lập các liên kết trao đổi động lượng tại ranh giới 1D-2D đòi hỏi người dùng phải can thiệp thủ công rất nhiều, dễ phát sinh bất ổn định số học và vẫn bị giới hạn về quy mô miền tính toán.")
    add_p("3. Thời kỳ mô hình thủy lực hai chiều thuần túy trên CPU (Fully 2D CPU Models):")
    add_p("Vào đầu những năm 2000, với sự gia tăng mạnh mẽ của năng lực máy tính cá nhân và sự sẵn có của dữ liệu mô hình số độ cao (DEM) từ vệ tinh, các mô hình giải phương trình nước nông hai chiều đầy đủ (2D Shallow Water Equations - SWE) trên CPU như Telemac-2D, TUFLOW, InfoWorks ICM, và HEC-RAS 2D (từ phiên bản 5.0) đã được ứng dụng rộng rãi trong ngành kỹ thuật thủy lợi. Các mô hình này mô tả tương đối đầy đủ các hiện tượng lan truyền sóng lũ, phản xạ sóng, nước dâng và dòng xoáy cục bộ. Tuy nhiên, hạn chế lớn nhất của mô hình 2D giải trên CPU là chi phí thời gian tính toán lớn. Phương trình nước nông là hệ phương trình vi phân phi tuyến dạng hyperbolic; để đảm bảo tính ổn định số học theo điều kiện Courant-Friedrichs-Lewy (CFL), bước thời gian dt bị giới hạn nghiêm ngặt khi kích thước ô lưới dx giảm xuống 30m hoặc 10m. Đối với một lưu vực rộng 2.000 - 4.000 km² với hàng triệu ô tính toán, một kịch bản mô phỏng lũ 5 ngày trên CPU đa nhân hiện đại thường đòi hỏi từ 15 đến 30 ngày chạy máy liên tục, khó đáp ứng yêu cầu cung cấp thông tin kịp thời phục vụ công tác phòng chống lũ.")
    add_p("4. Thời kỳ mô hình thủy lực 2D gia tốc trên GPU (GPU-accelerated 2D Hydrodynamic Models):")
    add_p("Trong vòng một thập kỷ qua, việc ứng dụng kiến trúc tính toán song song hàng loạt trên chip đồ họa (Graphics Processing Unit - GPU) sử dụng nền tảng NVIDIA CUDA đã đem lại bước tiến đáng kể trong cơ học thủy khí tính toán [24]. Chip GPU hiện đại sở hữu hàng nghìn nhân tính toán độc lập (CUDA cores), phù hợp với cấu trúc lưới của phương pháp thể tích hữu hạn (Finite Volume Method), nơi mà thông lượng qua các cạnh của từng ô lưới có thể được tính toán đồng thời song song mà không cần phụ thuộc lẫn nhau. Các công trình của Bates et al. (2010) [4], Vacondio et al. (2014) [24], và sự ra đời của mô hình mã nguồn mở BG_Flood bởi Bosserelle et al. (2020) [3] tại Viện Nghiên cứu Nước và Khí quyển Quốc gia New Zealand (NIWA) đã chứng minh khả năng tăng tốc độ mô phỏng từ 50 đến hơn 120 lần so với CPU cùng thế hệ. Một kịch bản mô phỏng lũ diện rộng trên lưới 2.099 x 2.099 ô (hơn 4.4 triệu ô lưới) kéo dài 120 giờ thực tế chỉ mất khoảng 60 đến 70 giờ tính toán trên một card đồ họa GPU thương mại, đạt tốc độ nhanh hơn thời gian thực (1.8x real-time), giúp việc mô phỏng thủy lực 2D độ phân giải cao trên quy mô toàn lưu vực trở nên khả thi và hiệu quả về mặt thời gian.")

    add_h("1.1.2. Tổng quan các nghiên cứu mô phỏng ngập lụt tại Việt Nam", level=3)
    add_p("Tại Việt Nam, nghiên cứu mô phỏng ngập lụt và thủy lực sông ngòi luôn là đề tài thu hút sự quan tâm đặc biệt của các cơ quan quản lý và giới khoa học thủy lợi do tính chất phức tạp của thiên tai bão lũ miền Trung và ngập lụt triều cường tại đồng bằng sông Cửu Long. Các giai đoạn nghiên cứu trong nước diễn ra song hành cùng sự chuyển giao công nghệ quốc tế:")
    add_p("Trong giai đoạn từ năm 1995 đến 2010, các mô hình 1D như WENDY (Viện Khoa học Thủy lợi Việt Nam phát triển), KODU (Đại học Thủy lợi), và bộ phần mềm MIKE 11 của Đan Mạch đã được ứng dụng sâu rộng trong các dự án quy hoạch thoát lũ sông Hồng, sông Thái Bình và hệ thống kênh rạch đồng bằng sông Cửu Long. Các nghiên cứu này giải quyết tốt bài toán truyền lũ tổng thể trong mạng lưới sông chính nhưng chưa thể cung cấp thông tin không gian chi tiết về ngập lụt trên bãi tràn.")
    add_p("Từ năm 2010 đến nay, các nghiên cứu ứng dụng mô hình 2D bắt đầu nở rộ. Tiêu biểu như công trình của Trịnh Thu Phương và cộng sự (2020) [17] đã ứng dụng mô hình Mike 11 kết hợp Mike 21 để mô phỏng ngập lụt hạ du lưu vực sông Ba dưới tác động của biến đổi khí hậu và quy trình vận hành liên hồ chứa. Lê Văn Hưng và Hà Minh Cường (2021) [19] đã nghiên cứu đánh giá nguy cơ ngập lụt đô thị bằng mô hình thủy lực 2D kết hợp công nghệ GIS tại khu vực miền Trung. Tuy nhiên, phần lớn các nghiên cứu trong nước từ trước đến nay vẫn chủ yếu dựa vào các phần mềm thương mại, chạy trên nền tảng CPU với độ phân giải lưới tương đối thô (90m đến 250m) do hạn chế về năng lực tính toán. Đồng thời, công tác kiểm chứng kết quả mô phỏng đa phần chỉ dừng lại ở việc so sánh mực nước tại một vài trạm thủy văn quan trắc thưa thớt dọc sông (như trạm Củng Sơn trên sông Ba), còn thiếu dữ liệu vết ngập diện rộng trên các cánh đồng.")
    add_p("Do đó, việc tiếp cận và ứng dụng mô hình thủy lực mã nguồn mở thế hệ mới BG_Flood trên nền tảng tính toán GPU kết hợp kiểm chuẩn đa chiều bằng ảnh vệ tinh viễn thám radar Sentinel-1 SAR trong đồ án này là một hướng tiếp cận hiệu quả, giải quyết đồng thời cả hai bài toán: tối ưu hóa thời gian tính toán và kiểm định không gian khách quan.")

    add_h("1.2. Cơ sở lý thuyết về lũ lụt và các nhân tố hình thành lũ tại Nam Trung Bộ", level=2)
    add_h("1.2.1. Định nghĩa và phân loại các loại hình ngập lụt", level=3)
    add_p("Lũ lụt là một hiện tượng tự nhiên phức tạp, được định nghĩa là sự dâng cao mực nước của các thủy vực tự nhiên (sông, suối, hồ, biển) vượt qua khỏi bờ chứa thông thường, làm ngập chìm tạm thời các diện tích đất đai vốn bình thường khô ráo [2]. Trong khoa học thủy văn và quản lý thiên tai, lũ lụt thường được phân loại thành các dạng chính:")
    add_p("1. Lũ sông (Fluvial / Riverine Flood): Xuất hiện khi lượng nước mưa tích tụ trên toàn lưu vực vượt quá khả năng chuyển tải của lòng dẫn sông, khiến mực nước dâng tràn hai bên bờ đê và lan tỏa vào các thung lũng, bãi bồi ven sông. Lũ sông thường có thời gian duy trì từ vài ngày đến hàng tuần.")
    add_p("2. Lũ quét (Flash Flood): Là loại hình lũ xảy ra bất ngờ tại các lưu vực sông suối miền núi có độ dốc lớn, hình thành chỉ sau một trận mưa có cường suất cực lớn trong thời gian ngắn (vài giờ). Lũ quét mang theo lượng bùn cát, đá tảng lớn với động năng dòng chảy cao.")
    add_p("3. Ngập lụt do mưa cục bộ (Pluvial / Surface Water Flood): Xảy ra khi lượng mưa rơi trực tiếp trên bề mặt vượt quá khả năng thấm của đất và năng lực tiêu thoát của hệ thống thoát nước tự nhiên hoặc nhân tạo, gây ngập úng các vùng trũng cục bộ độc lập với dòng chảy sông.")
    add_p("4. Ngập lụt ven biển do triều cường và nước dâng do bão (Coastal / Storm Surge Flood): Hình thành do sự kết hợp giữa triều cường thiên văn và hiện tượng nước biển dâng do áp suất khí quyển giảm thấp và gió bão thổi dồn nước vào bờ.")
    add_p("Tại hạ lưu sông Ba (Phú Yên), ngập lụt trận tháng 11/2021 là một tổ hợp lũ lụt hỗn hợp (Compound Flooding), kết hợp đồng thời giữa lũ sông lớn từ thượng nguồn đổ về, mưa nội đồng diện rộng và triều cường dâng cao cản trở dòng thoát lũ tại cửa biển Đà Diễn.")

    add_h("1.2.2. Các nhân tố khí tượng thủy văn đặc thù tại lưu vực sông Ba", level=3)
    add_p("Sông Ba (còn gọi là sông Đà Rằng ở hạ lưu) là dòng sông lớn nhất vùng Duyên hải Nam Trung Bộ với chiều dài dòng chính khoảng 374 km và tổng diện tích lưu vực lên tới 13.900 km². Lưu vực sông Ba trải dài trên địa bàn các tỉnh Kon Tum, Gia Lai, Đắk Lắk và Phú Yên trước khi đổ ra biển Đông tại TP. Tuy Hòa.")
    add_p("Cơ chế hình thành các trận lũ trên lưu vực sông Ba chịu sự chi phối của ba nhân tố khí tượng - thủy văn đặc thù:")
    add_p("Thứ nhất, tính chất địa hình phân bậc mạnh mẽ: Thượng nguồn sông Ba bắt nguồn từ đỉnh Ngọc Linh có độ cao trên 2.000m thuộc dãy Trường Sơn, chảy qua cao nguyên Pleiku và An Khê với địa hình đồi núi dốc đứng. Tuy nhiên, khi chảy đến địa phận huyện Tây Hòa và Phú Hòa (tỉnh Phú Yên), thung lũng sông mở rộng đột ngột ra vùng đồng bằng phù sa Tuy Hòa tương đối bằng phẳng với cao độ phổ biến chỉ từ 2m đến 8m so với mực nước biển. Sự chuyển tiếp từ lòng dẫn dốc hẹp sang đồng bằng trũng rộng khiến động năng dòng lũ nhanh chóng chuyển hóa thành thế năng dâng cao mặt nước khi gặp các vật cản.")
    add_p("Thứ hai, chế độ mưa tập trung cường suất lớn: Nằm ở sườn đông dãy Trường Sơn, lưu vực sông Ba là tâm đón gió mùa Đông Bắc ẩm từ biển thổi vào. Mùa mưa tại đây diễn ra muộn (từ tháng 9 đến tháng 12) nhưng tập trung tới 70 - 80% tổng lượng mưa cả năm. Khi có sự kết hợp đồng thời giữa hoàn lưu bão/áp thấp nhiệt đới trên biển Đông với không khí lạnh tăng cường từ phía Bắc và nhiễu động đới gió Đông trên cao, mưa lớn sẽ xảy ra trên diện rộng với tổng lượng mưa có thể đạt từ 500 đến gần 1.000 mm trong vòng 72 đến 96 giờ.")
    add_p("Thứ ba, sự điều tiết xả lũ của chuỗi hồ chứa thủy điện bậc thang: Trên dòng chính sông Ba và các nhánh phụ lưu lớn hiện có nhiều nhà máy thủy điện đang vận hành, trong đó bậc thang cuối cùng sát đồng bằng Tuy Hòa là Thủy điện Sông Ba Hạ (công suất 220 MW, dung tích phòng lũ hạn chế). Trong các trận mưa bão lớn, do các hồ phía trên (An Khê - Kanak, Krông H'năng) đồng loạt xả nước để bảo đảm an toàn hồ đập, lưu lượng nước đổ về hồ Sông Ba Hạ dâng lên rất nhanh. Khi mực nước hồ chạm ngưỡng dâng bình thường (105.0m), hồ Sông Ba Hạ bắt buộc phải mở toàn bộ các cửa van cung xả lũ xuống hạ du với lưu lượng xả lớn (trên 9.000 m³/s), khiến mực nước dâng nhanh trên diện rộng tại đồng bằng Tuy Hòa.")

    add_h("1.3. Công nghệ Viễn thám và dữ liệu Radar khẩu độ tổng hợp (SAR) trong nghiên cứu ngập lụt", level=2)
    add_h("1.3.1. Nguyên lý vật lý của Radar khẩu độ tổng hợp (SAR)", level=3)
    add_p("Viễn thám (Remote Sensing) là phương pháp thu thập thông tin về các đối tượng hoặc hiện tượng trên bề mặt Trái Đất mà không cần tiếp xúc vật lý trực tiếp. Các hệ thống viễn thám quang học thụ động (như Landsat 8/9, Sentinel-2) dựa vào nguồn bức xạ phản xạ từ ánh sáng Mặt Trời trong dải sóng nhìn thấy và hồng ngoại. Trong các đợt thiên tai lũ lụt, bầu trời thường xuyên bị che phủ bởi mây bão dày đặc (Cloud cover > 90%), khiến các bộ cảm biến quang học gặp nhiều hạn chế khi quan sát bề mặt đất.")
    add_p("Để giải quyết bài toán này, công nghệ Radar khẩu độ tổng hợp (Synthetic Aperture Radar - SAR) là công cụ quan trọng của ngành viễn thám hiện đại [9], [10]. SAR là hệ thống viễn thám vi ba chủ động (Active Microwave Remote Sensing). Vệ tinh mang theo ăng-ten tự phát ra các chùm xung sóng điện từ ở dải tần số vi ba (Microwave) hướng xuống mặt đất và sau đó thu nhận tín hiệu phản xạ (tín hiệu tán xạ ngược - Backscatter) dội trở lại.")
    add_p("Nguyên lý 'khẩu độ tổng hợp' (Synthetic Aperture): Trong vật lý quang học và radar truyền thống, độ phân giải góc phương vị (Azimuth Resolution - độ phân giải theo hướng bay của vệ tinh) tỉ lệ thuận với bước sóng điện từ λ và tỉ lệ nghịch với chiều dài vật lý của ăng-ten L (θ ≈ λ / L). Đối với sóng vi ba có bước sóng vài cm, để đạt được độ phân giải không gian mặt đất 10m từ độ cao quỹ đạo 700 km, một ăng-ten radar thông thường sẽ phải có chiều dài lên tới hàng km – điều khó khả thi về mặt kỹ thuật vũ trụ. Công nghệ SAR giải quyết vấn đề này bằng cách tận dụng sự chuyển động dọc theo quỹ đạo của vệ tinh: Ăng-ten radar liên tục phát và thu các xung sóng khi di chuyển qua một vị trí mục tiêu trên mặt đất. Bằng cách số hóa, lưu trữ biên độ và pha của các tín hiệu phản xạ thu được dọc theo quỹ đạo bay, hệ thống xử lý tín hiệu số mặt đất sẽ tổng hợp (tái tạo) lại tín hiệu tương đương như một ăng-ten ảo duy nhất có chiều dài bằng toàn bộ quãng đường vệ tinh di chuyển trong thời gian quan sát mục tiêu. Nhờ đó, SAR đạt được độ phân giải không gian cao (dưới 10m) độc lập với độ cao bay của vệ tinh.")

    add_h("1.3.2. Cơ chế tán xạ sóng radar trên mặt nước phẳng và bề mặt đất", level=3)
    add_p("Khả năng phát hiện và lập bản đồ vùng ngập nước của ảnh SAR dựa trên sự tương phản rõ rệt về cơ chế tán xạ sóng điện từ giữa mặt nước và các loại lớp phủ bề mặt khác [10]:")
    add_p("1. Cơ chế phản xạ gương trên mặt nước phẳng (Specular Reflection):")
    add_p("Hằng số điện môi (Dielectric Constant) của nước lỏng ở tần số vi ba là rất lớn (ε_water ≈ 80) so với đất khô (ε_soil ≈ 3 - 6). Do đó, bề mặt nước hoạt động như một chất phản xạ điện từ mạnh. Tuy nhiên, do bề mặt nước ngập trong lũ lụt (đặc biệt tại các vùng đồng bằng lưu tốc nhỏ) tương đối phẳng nhẵn so với bước sóng radar (băng C có bước sóng λ ≈ 5.6 cm), hiện tượng tán xạ tuân theo định luật phản xạ quang học phẳng của Snell. Toàn bộ chùm sóng radar phát tới mặt nước với góc tới nghiêng θ sẽ bị phản xạ đổi hướng theo chiều ngược lại (Specular Reflection), hướng ra xa khỏi quỹ đạo vệ tinh. Kết quả là hầu như không có năng lượng sóng phản xạ quay trở lại máy thu của radar. Do đó, hệ số tán xạ ngược radar (Sigma Nought, σ⁰) của mặt nước ngập có giá trị rất nhỏ (thường dao động từ -25 dB đến -15 dB), hiển thị trên ảnh xám radar bằng các mảng màu tối rõ rệt.")
    add_p("2. Cơ chế tán xạ khuếch tán trên bề mặt cạn (Diffuse / Rough Surface Scattering):")
    add_p("Ngược lại, bề mặt đất cạn, sỏi đá, đường sá và thảm thực vật có độ gồ ghề bề mặt tương đương hoặc lớn hơn bước sóng radar. Sóng radar khi chạm vào các bề mặt này sẽ bị tán xạ đẳng hướng về mọi góc trong không gian (Diffuse Scattering), trong đó một phần đáng kể năng lượng sóng phản xạ quay ngược trở lại ăng-ten vệ tinh. Do đó, giá trị σ⁰ của đất cạn cao hơn nhiều (thường từ -12 dB đến -5 dB), hiển thị bằng các tông màu sáng.")
    add_p("3. Cơ chế tán xạ góc đôi tại khu vực công trình và thực vật nhô (Double-bounce Scattering):")
    add_p("Tại các khu vực đô thị có nhà cửa hoặc vùng đất ngập nước có thực vật thân gỗ nhô lên khỏi mặt nước, sóng radar sẽ trải qua hiện tượng phản xạ kép: sóng chạm vào mặt nước phẳng phản xạ tới tường nhà/thân cây, rồi dội thẳng ngược trở lại ăng-ten vệ tinh. Hiện tượng này làm tăng cường độ tín hiệu phản xạ (σ⁰ có thể đạt giá trị dương từ 0 dB đến +10 dB), hiển thị bằng các điểm sáng rõ trên ảnh.")
    add_p("4. Giới hạn vật lý của kênh sóng C-band SAR trong quan sát ngập lụt:")
    add_p("Mặc dù có ưu thế quan sát không phụ thuộc mây che phủ, kênh sóng C-SAR (bước sóng ngắn λ ≈ 5.6 cm) tồn tại hai giới hạn vật lý tự nhiên cần được tính đến trong kiểm chuẩn mô hình: (i) Hiện tượng suy giảm tín hiệu dưới tán thực vật dày (sub-canopy flooding) – do bước sóng băng C ngắn nên khó xuyên qua tán cây rừng rậm rạp như băng L (λ ≈ 24 cm), dẫn đến nguy cơ bỏ sót vết ngập (sai số âm tính giả - FN) tại các dải thực vật ngập mặn ven đầm hoặc cây bụi ven sông; (ii) Hiện tượng mặt nước động do gió bão mạnh (wind-roughened water surface) – gió lớn tạo sóng mặt nước có quy mô gồ ghề tương đương bước sóng vi ba, làm gia tăng tán xạ khuếch tán và nâng cao giá trị σ⁰, có thể khiến thuật toán phân ngưỡng nhầm lẫn giữa mặt nước động và mặt đất cạn.")

    add_h("1.3.3. Đặc tính kỹ thuật của chùm vệ tinh Sentinel-1", level=3)
    add_p("Chùm vệ tinh Sentinel-1 thuộc Hợp phần Quan sát Trái Đất Copernicus của Liên minh Châu Âu (EU) và Cơ quan Vũ trụ Châu Âu (ESA) vận hành, bao gồm hai vệ tinh bay cùng quỹ đạo Sentinel-1A (phóng năm 2014) và Sentinel-1B (phóng năm 2016) [9]. Vệ tinh bay trên quỹ đạo đồng bộ Mặt Trời (Sun-synchronous orbit) ở độ cao danh định 693 km, độ nghiêng quỹ đạo 98.18°, chu kỳ lặp lại quỹ đạo chụp ảnh là 12 ngày cho một vệ tinh đơn lẻ và 6 ngày khi kết hợp cả hai vệ tinh.")
    add_p("Bộ cảm biến chính trên Sentinel-1 là hệ thống radar khẩu độ tổng hợp băng C (C-SAR) hoạt động ở tần số trung tâm 5.405 GHz (bước sóng λ = 5.546 cm). Chế độ chụp ảnh tiêu chuẩn trên đất liền là chế độ dải rộng giao thoa (Interferometric Wide Swath - IW). Ở chế độ này, dải quét ảnh có độ rộng mặt đất lên tới 250 km, cung cấp dữ liệu phân cực kép đồng thời (Dual-polarization): VV (phát thẳng đứng - thu thẳng đứng) và VH (phát thẳng đứng - thu nằm ngang).")
    add_p("Trong nghiên cứu ngập lụt, kênh phân cực đồng (VV) được chứng minh là có độ nhạy vượt trội đối với sự tương phản giữa bề mặt nước và đất so với kênh phân cực chéo (VH). Dữ liệu sử dụng trong đồ án là sản phẩm Level-1 Ground Range Detected (GRD) với kích thước pixel lấy mẫu 10m x 10m, cung cấp dữ liệu cường độ biên độ đã được hiệu chỉnh chiếu lên mặt ellipsoid Trái Đất WGS84, có độ tin cậy hình học cao.")

    add_h("1.3.4. Các phương pháp phân ngưỡng trích xuất vết ngập (Thuật toán Otsu)", level=3)
    add_p("Để chuyển đổi ảnh biên độ radar liên tục σ⁰ (dạng dB) thành bản đồ nhị phân phân loại ngập lụt (1 = Ngập nước, 0 = Không ngập), phương pháp phân ngưỡng thống kê (Statistical Thresholding) là phương pháp tiếp cận phổ biến và khách quan. Trong đó, thuật toán phân ngưỡng toàn cục Otsu (Otsu Thresholding Method - 1979) [5] được sử dụng rộng rãi nhờ tính khách quan và hiệu quả tính toán.")
    add_p("Thuật toán Otsu dựa trên giả thiết biểu đồ tần số histogram của ảnh xám chứa hai phân bố lớp chuẩn (Bimodal distribution) đại diện cho lớp nền (Background - đất cạn) và lớp đối tượng (Foreground - mặt nước ngập). Thuật toán tự động tìm kiếm một ngưỡng phân tách tối ưu T* trong toàn bộ miền giá trị mức xám [1, L] sao cho phương sai giữa hai lớp (Inter-class variance, σ_B²) đạt giá trị cực đại:")
    add_p("Giả sử ảnh có N pixel với các mức xám từ 1 đến L. Số lượng pixel ở mức xám i là n_i. Xác suất xuất hiện của mức xám i là p_i = n_i / N. Khi chia ảnh thành hai lớp C0 (mức xám [1, T]) và C1 (mức xám [T+1, L]), xác suất xuất hiện của lớp C0 và C1 lần lượt là:")
    add_p("ω0(T) = ∑_{i=1}^T p_i ;  ω1(T) = ∑_{i=T+1}^L p_i = 1 - ω0(T)")
    add_p("Giá trị mức xám trung bình của hai lớp lần lượt là:")
    add_p("μ0(T) = (∑_{i=1}^T i · p_i) / ω0(T) ;  μ1(T) = (∑_{i=T+1}^L i · p_i) / ω1(T)")
    add_p("Giá trị mức xám trung bình của toàn bộ ảnh là μ_T = ω0·μ0 + ω1·μ1. Phương sai giữa hai lớp được định nghĩa là:")
    add_p("σ_B²(T) = ω0(T) · (μ0(T) - μ_T)² + ω1(T) · (μ1(T) - μ_T)² = ω0(T) · ω1(T) · [μ0(T) - μ1(T)]²")
    add_p("Ngưỡng tối ưu T* được xác định bằng cách giải bài toán cực đại hóa: T* = argmax_{1 ≤ T < L} [ σ_B²(T) ].")
    add_p("Ưu điểm của thuật toán Otsu là hoàn toàn tự động, phi tham số (Non-parametric), không phụ thuộc vào sự phỏng đoán chủ quan, mang lại ranh giới phân tách nước ngập có tính ổn định thống kê cao.")

    add_h("1.4. Hệ thống thông tin địa lý (GIS) và mô hình số độ cao (DEM)", level=2)
    add_h("1.4.1. Khái niệm và phân biệt giữa DEM, DTM và DSM", level=3)
    add_p("Trong mô hình hóa thủy văn và thủy lực 2D, mô hình số độ cao là tập dữ liệu địa không gian quan trọng, đóng vai trò quyết định hướng truyền sóng lũ, vận tốc dòng chảy và phạm vi ngập úng. Trong thực tế nghiên cứu cần phân biệt rõ ba khái niệm mô hình độ cao:")
    add_p("1. DSM (Digital Surface Model - Mô hình bề mặt số): Đại diện cho bề mặt cao trình của tất cả các đối tượng nằm trên lớp phản xạ đầu tiên của cảm biến viễn thám, bao gồm mái nhà, công trình xây dựng, cầu cống, đường dây điện và tán cây rừng.")
    add_p("2. DEM/DTM (Digital Elevation / Terrain Model - Mô hình địa hình số trần): Thể hiện cao độ thực của bề mặt đất tự nhiên (Bare-earth terrain), đã loại bỏ các vật thể nhân tạo và thảm phủ thực vật bên trên.")
    add_p("Trong mô phỏng thủy lực dòng tràn, việc sử dụng trực tiếp mô hình bề mặt số (DSM) chưa loại bỏ lớp phủ có thể dẫn đến các sai số hình học đáng kể: tán cây rừng ven sông và các công trình nhân tạo trên bãi bồi tạo thành các rào cản giả tạo cản trở dòng chảy tràn; các cầu giao thông bắc qua sông tạo thành các chướng ngại vật chặn dòng chính, gây ngập úng giả tạo ở thượng lưu và thiếu hụt dòng chảy ở hạ lưu. Do đó, việc sử dụng mô hình DTM trần (Bare-earth) – tiêu biểu là bộ dữ liệu FABDEM (Forest And Buildings removed DEM) 30m phát triển bởi Hawker et al. (2022) [8] – là điều kiện quan trọng để phản ánh đúng quy luật dòng chảy thủy lực.")

    add_h("1.4.2. Vấn đề rào cản nhân tạo (Artificial Barriers) và sai số dòng chảy", level=3)
    add_p("Mặc dù đã sử dụng mô hình DTM trần, các mô hình thủy lực 2D quy mô lưu vực vẫn phải đối mặt với một vấn đề kỹ thuật: Vấn đề rào cản nhân tạo do độ phân giải ô lưới (Grid Resolution Effect) [15], [16].")
    add_p("Trong thực tế, các tuyến đê bao ven sông, đường quốc lộ và đường sắt thường được đắp cao hơn mặt ruộng từ 1.5m đến 4.0m. Dưới các tuyến đê và đường này luôn có hệ thống các cống tiêu thoát nước (Culverts), cầu máng hoặc cầu chui dân sinh với khẩu độ từ 1m đến 5m để tiêu thoát lũ nội đồng ra sông hoặc ngược lại. Tuy nhiên, khi chuyển đổi bản đồ địa hình sang lưới ô vuông số học kích thước 30m x 30m (hoặc 90m x 90m), kích thước của một ô lưới lớn hơn nhiều so với khẩu độ cống ngầm. Thuật toán lấy mẫu địa hình gán cho toàn bộ ô lưới 30m giá trị cao độ trung bình của mặt đê/mặt đường. Hậu quả là khẩu độ thoát nước của các cống ngầm không được phản ánh, biến hệ thống công trình giao thông và đê điều thành các rào cản địa hình liên tục.")
    add_p("Khi mô hình thủy lực vận hành, dòng nước dâng trong lòng sông bị các rào cản ô lưới này ngăn lại, không thể tràn qua để vào đồng bằng Tuy Hòa, dẫn đến sai số bỏ sót vùng ngập (False Negative) tương đối lớn khi so sánh với ảnh vệ tinh thực tế. Để xử lý vấn đề này, các kỹ thuật can thiệp hình thái học như mở đường tràn cục bộ (Levee Breaching) hoặc san phẳng hình thái (Morphological Carving) được áp dụng nhằm khôi phục khả năng thoát lũ qua bờ.")

    add_h("1.4.3. Chỉ số địa hình thủy văn HAND (Height Above Nearest Drainage)", level=3)
    add_p("Chỉ số địa hình thủy văn HAND (Height Above Nearest Drainage) do Nobre et al. (2011) [6] đề xuất là một phương pháp hiệu quả trong phân tích địa hình thủy văn không gian. Khác với cao trình tuyệt đối so với mực nước biển (Z), chỉ số HAND chuẩn hóa độ cao của từng điểm địa hình dựa trên hiệu số cao độ tương đối giữa điểm đó với điểm lòng dẫn thoát nước gần nhất mà dòng chảy từ điểm đó sẽ đổ vào theo mạng lưới hướng dòng chảy D8 (Flow Direction):")
    add_p("HAND(x) = Z(x) - Z(drainage(x))")
    add_p("Ý nghĩa vật lý của chỉ số HAND nằm ở chỗ nó phản ánh khả năng ngập lụt tự nhiên của một vị trí theo nguyên lý trọng trường: Dòng nước lũ từ lòng sông chỉ có thể dâng tràn vào các vùng đất có cao trình HAND nhỏ hơn độ dâng mực nước đỉnh lũ trong lòng sông. Bằng cách phân loại bản đồ HAND thành các đới:")
    add_p("- Đới bãi bồi tự nhiên (Natural Floodplain): HAND <= 3.5m. Đây là vùng trũng thấp ven sông, có nguy cơ ngập lụt cao trong các trận lũ vừa và lớn.")
    add_p("- Đới chuyển tiếp (Transition Zone): 3.5m < HAND <= 10.0m. Vùng đất cao ven bãi bồi, chỉ ngập trong các trận lũ cực đoan.")
    add_p("- Đới đồi núi cao (Steep Relief): HAND > 10.0m. Vùng đồi núi có sườn dốc lớn, hầu như không bị ngập lụt sông diện rộng.")
    add_p("Trong đồ án này, bản đồ HAND đóng vai trò như một bộ kiểm chuẩn địa hình độc lập (Topographic Plausibility Benchmark) để đánh giá xem nước mô phỏng có phân bố phù hợp theo quy luật thủy lực trọng trường tự nhiên hay không.")

    add_h("1.5. Mô hình thủy lực 2 chiều mã nguồn mở BG_Flood trên GPU", level=2)
    add_p("BG_Flood (Block-Adaptive GPU-accelerated Flood Model) là phần mềm mã nguồn mở chuyên dụng mô phỏng thủy lực và ngập lụt được phát triển từ năm 2020 bởi TS. Cyprien Bosserelle và nhóm nghiên cứu tại Viện NIWA (New Zealand) [3]. Mô hình được thiết kế để khai thác năng lực tính toán song song của kiến trúc GPU NVIDIA CUDA.")
    add_p("Mô hình giải hệ phương trình nước nông 2 chiều phi tuyến hoàn chỉnh (Nonlinear 2D Shallow Water Equations) dựa trên phương pháp thể tích hữu hạn (Finite Volume Method) dạng Godunov với độ chính xác bậc 2. Điểm đặc sắc của BG_Flood là cấu trúc quản lý ô lưới theo từng khối (Block-Adaptive Data Structure). Toàn bộ miền tính toán được phân chia thành các khối ô lưới vuông (Block) có kích thước cố định (ví dụ 16x16 hoặc 32x32 ô lưới). Mỗi khối ô lưới này được ánh xạ trực tiếp vào một khối luồng tính toán (Thread Block) trong vi kiến trúc phần cứng của GPU, tận dụng bộ nhớ chia sẻ tốc độ cao (Shared Memory) của chip đồ họa và giảm thiểu độ trễ truy xuất bộ nhớ toàn cục (Global Memory Latency).")
    add_p("Nhờ tối ưu hóa ở mức phần cứng, BG_Flood cho phép mô phỏng các lưu vực có quy mô hàng triệu ô lưới với tốc độ cao, hỗ trợ xuất kết quả chuẩn NetCDF4 với đầy đủ các trường thủy lực (h, zs, u, v) tại từng bước thời gian chỉ định, tạo tiền đề thuận lợi cho việc tích hợp với các công cụ viễn thám và hệ thống thông tin địa lý GIS.")

    doc.add_page_break()
    print("Xong Chương 1.")
